82	                status: statusToSave ?? draft.status,
83	                actions: draft.actions,
84	                edges: draft.edges
85	            },
86	            {
87	                onSuccess: (response) => {
88	                    setDraft(response.automations[0]);
89	                    setEditState('idle');
90	                },
91	                onError: () => setEditState(errorState)
92	            }
93	        );
94	    };
95	
96	    let isConfirmUnpublishAlertOpen = false;
97	    let isEditRequestActive = false;
98	    let isSaveButtonEnabled = !!draft && draft.actions.length > 0 && draft.status === 'inactive' && hasUnsavedChanges;
99	    let saveButtonVariant: ButtonProps['variant'] = 'secondary';
100	    let saveButtonChildren: React.ReactNode = 'Save';
101	    let isPublishButtonEnabled = !!draft && draft.actions.length > 0 && (draft.status === 'inactive' || hasUnsavedChanges);
102	    let publishButtonVariant: ButtonProps['variant'] = 'default';
103	    let publishButtonChildren: React.ReactNode = draft?.status === 'active'
104	        ? (hasUnsavedChanges ? 'Publish changes' : 'Published')
105	        : 'Publish';
106	    let isTurnOffButtonEnabled = true;
107	    let turnOffButtonChildren: React.ReactNode = 'Turn off';
108	    switch (editState) {
109	    case 'idle':
110	        break;
111	    case 'saving':
112	        isEditRequestActive = true;
113	        isSaveButtonEnabled = false;
114	        isPublishButtonEnabled = false;
115	        isTurnOffButtonEnabled = false;
116	        saveButtonChildren = (
117	            <>
118	                <LoadingIndicator size='sm' />
119	                <span className='sr-only'>Saving...</span>
120	            </>
121	        );
122	        break;
123	    case 'publishing':
124	        isEditRequestActive = true;
125	        isSaveButtonEnabled = false;
126	        isPublishButtonEnabled = false;
127	        isTurnOffButtonEnabled = false;
128	        publishButtonChildren = (
129	            <>
130	                <LoadingIndicator color='light' size='sm' />
131	                <span className='sr-only'>Publishing...</span>
132	            </>
133	        );
134	        break;
