168	        const _exhaustive: never = editState;
169	        throw new Error(`Unhandled edit state: ${_exhaustive}`);
170	    }
171	    }
172	
173	    const onConfirmUnpublishOpenChange = (open: boolean): void => {
174	        setEditState((oldEditState) => {
175	            switch (oldEditState) {
176	            case 'idle':
177	            case 'failed to save':
178	            case 'failed to publish':
179	                return open ? 'confirming unpublish' : oldEditState;
